function branchWordTarget(words, index) {
  const immediate = words[index] & 0xFFFF;
  const signed = immediate & 0x8000 ? immediate - 0x10000 : immediate;
  return index + 1 + signed;
}
function luiOriAddress(words, index) {
  return ((((words[index] & 0xFFFF) << 16) | (words[index + 1] & 0xFFFF)) >>> 0);
}
function hasLuiOriAddress(words, address) {
  for (let index = 0; index + 1 < words.length; index++) {
    if (luiOriAddress(words, index) === address) return true;
  }
  return false;
}
const zeroFallbackIndex = selectionResolverWords.findIndex(word =>
  (word & 0xFFFF0000) === 0x10400000);
const profilePointerCompareIndex = selectionResolverWords.findIndex(word =>
  (word & 0xFFFF0000) === 0x146D0000);
const profileExhaustedIndex = selectionResolverWords.findIndex(word =>
  (word & 0xFFFF0000) === 0x19600000);
const selectedReturnIndex = selectionResolverWords.indexOf(0x24420100);
const leaderClassLoadIndex = selectionResolverWords.findIndex(word =>
  word === OB64.squad._enc.lbu('v0', 16, 't2'));
const stagedClassStoreIndex = selectionResolverWords.findIndex(word =>
  word === OB64.squad._enc.sw('v0', 0, 't0'));
const matchTokenStoreIndex = selectionResolverWords.findIndex(word => word === 0xAD0E0008);
const matchSuccessBranchIndex = selectionResolverWords.findIndex((word, index) =>
  index > matchTokenStoreIndex && (word & 0xFFFF0000) === 0x10000000);
