const restoredArchives = OB64.findArchives(restored);
const retailArchives = OB64.findArchives(masterZ64);
check('message removal restores the empty entry while preserving following archive offsets',
  OB64.runtimeOverrides.buildBanditsMessageArchiveWrite(restored, false) === null &&
  restoredArchives[815].offset === retailArchives[815].offset &&
  restoredArchives[816].offset === retailArchives[816].offset);

