console.log('\n-- weighted boundaries and revision profiles --');
function weightedSlot(weights, rng) {
  const remainder = rng % weights.reduce((sum, value) => sum + value, 0);
  if (remainder < weights[0]) return 0;
  if (remainder - weights[0] < weights[1]) return 1;
  return 2;
}
check('weights 1:2:3 select the exact six-remainder boundary pattern',
  [0, 1, 2, 3, 4, 5].map(value => weightedSlot([1, 2, 3], value)).join(',') ===
  '0,1,1,2,2,2');
check('zero-weight slots are unreachable while a positive slot remains',
  Array.from({ length: 20 }, (_, value) => weightedSlot([0, 5, 0], value))
    .every(slot => slot === 1));
throws('zero-total weighted class fails closed', () =>
  OB64.runtimeOverrides.buildDropTable([{ classId: 0x45, weights: [0, 0, 0] }]),
  /zero total/i);

